entity demo is
  port (
    clk : in std_logic;
    rst_n : in std_logic;
    data : out std_logic_vector(7 downto 0);
    sda : inout std_logic
  );
end entity;

entity fifo is
  generic (WIDTH : integer := 8);
  port (
    d : in std_logic_vector(WIDTH-1 downto 0);
    q : out std_logic_vector(WIDTH-1 downto 0)
  );
end entity;

-- adder cell
entity adder is
  port (a, b : in std_logic; cin : in std_logic; s : out std_logic; cout : out std_logic);
end adder;

entity two is
  port (a : in bit; b : out bit);
end entity;
entity demo is
  port (clk : in std_logic);
end entity;
